16	// fakeEnv returns a getenv backed by a map, so DefaultSecretsPath never reads
17	// the real environment (and never the real HOME).
18	func fakeEnv(vars map[string]string) func(string) string {
19		return func(k string) string { return vars[k] }
20	}
21	
22	func TestDefaultSecretsPath(t *testing.T) {
23		tests := []struct {
24			name      string
25			env       map[string]string
26			ctx, ns   string
27			want      string
28			wantError bool
29		}{
30			{
31				name: "XDG_STATE_HOME wins",
32				env:  map[string]string{"XDG_STATE_HOME": "/state", "HOME": "/home/u", "USERPROFILE": "/home/u"},
33				ctx:  "datomir", ns: "nexus-bench",
34				want: filepath.Join("/state", "devdesk", "nexus-bench", "datomir", "nexus-bench", "secrets.json"),
35			},
36			{
37				name: "falls back to HOME/.local/state",
38				env:  map[string]string{"HOME": "/home/u", "USERPROFILE": "/home/u"},
39				ctx:  "datomir", ns: "nexus-bench",
40				want: filepath.Join("/home/u", ".local", "state", "devdesk", "nexus-bench", "datomir", "nexus-bench", "secrets.json"),
41			},
42			{
43				name: "an empty XDG_STATE_HOME counts as unset",
44				env:  map[string]string{"XDG_STATE_HOME": "", "HOME": "/home/u", "USERPROFILE": "/home/u"},
45				ctx:  "c", ns: "n",
46				want: filepath.Join("/home/u", ".local", "state", "devdesk", "nexus-bench", "c", "n", "secrets.json"),
47			},
48			{
49				name: "context and namespace make two different paths",
50				env:  map[string]string{"XDG_STATE_HOME": "/state"},
51				ctx:  "other", ns: "bench-2",
52				want: filepath.Join("/state", "devdesk", "nexus-bench", "other", "bench-2", "secrets.json"),
53			},
54			{
55				name:      "neither XDG_STATE_HOME nor HOME is an error",
56				env:       map[string]string{},
57				ctx:       "datomir",
58				ns:        "nexus-bench",
59				wantError: true,
60			},
61		}
62		for _, tt := range tests {
63			t.Run(tt.name, func(t *testing.T) {
64				got, err := DefaultSecretsPath(tt.ctx, tt.ns, fakeEnv(tt.env))
65				if tt.wantError {
66					if err == nil {
67						t.Fatalf("DefaultSecretsPath = %q, want an error", got)
68					}
69					return
70				}
71				if err != nil {
72					t.Fatalf("DefaultSecretsPath: %v", err)
73				}
74				if got != tt.want {
75					t.Errorf("DefaultSecretsPath = %q, want %q", got, tt.want)
76				}
77			})
78		}
79	}
