81	// secretsPathIn returns a store path two levels below a fresh temp dir, that
82	// does not exist yet: Save has to create the folders itself.
83	func secretsPathIn(t *testing.T) string {
84		t.Helper()
85		return filepath.Join(t.TempDir(), "ctx", "ns", "secrets.json")
86	}
