97	func TestFileStoreLoadAbsent(t *testing.T) {
98		store := newTestStore(t, secretsPathIn(t))
99		got, found, err := store.Load()
100		if err != nil {
101			t.Fatalf("Load on an absent file: %v", err)
102		}
