111	func TestFileStoreSaveLoadRoundTrip(t *testing.T) {
112		tests := []struct {
113			name string
114			in   Secrets
115		}{
116			{"all three fields", Secrets{AdminPassword: "a-1", PendingAdminPassword: "p-2", PullPassword: "REDACTED"}},
117			{"admin only", Secrets{AdminPassword: "a-1"}},
118			{"pending only (interrupted password change)", Secrets{PendingAdminPassword: "p-2"}},
119			{"characters JSON must escape", Secrets{AdminPassword: "REDACTED", PullPassword: "REDACTED"}},
120		}
121		for _, tt := range tests {
122			t.Run(tt.name, func(t *testing.T) {
123				store := newTestStore(t, secretsPathIn(t))
124				if err := store.Save(tt.in); err != nil {
125					t.Fatalf("Save: %v", err)
126				}
127				got, found, err := store.Load()
128				if err != nil {
129					t.Fatalf("Load: %v", err)
130				}
131				if !found {
132					t.Fatal("Load: found = false after Save")
133				}
134				if got != tt.in {
135					t.Errorf("Load = %+v, want %+v", got, tt.in)
136				}
137			})
138		}
