171	func TestFileStoreModes(t *testing.T) {
172		if runtime.GOOS == "windows" {
173			t.Skip("POSIX permission bits are not meaningful on Windows")
174		}
175		path := secretsPathIn(t)
176		store := newTestStore(t, path)
177	
178		// A file left by someone else with a wider mode must not keep it.
179		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
180			t.Fatal(err)
181		}
182		if err := os.WriteFile(path, []byte("{}"), 0o644); err != nil {
183			t.Fatal(err)
184		}
185	
186		if err := store.Save(Secrets{AdminPassword: "x"}); err != nil {
187			t.Fatal(err)
188		}
189		info, err := os.Stat(path)
190		if err != nil {
191			t.Fatal(err)
192		}
193		if got := info.Mode().Perm(); got != 0o600 {
194			t.Errorf("secrets file mode = %o, want 600", got)
195		}
196	
197		// A folder that Save creates is 0700.
198		fresh := secretsPathIn(t)
199		if err := newTestStore(t, fresh).Save(Secrets{AdminPassword: "x"}); err != nil {
200			t.Fatal(err)
201		}
202		for _, dir := range []string{filepath.Dir(fresh), filepath.Dir(filepath.Dir(fresh))} {
203			di, err := os.Stat(dir)
204			if err != nil {
205				t.Fatal(err)
206			}
207			if got := di.Mode().Perm(); got != 0o700 {
208				t.Errorf("folder %s mode = %o, want 700", dir, got)
209			}
210		}
211		fi, err := os.Stat(fresh)
212		if err != nil {
213			t.Fatal(err)
214		}
215		if got := fi.Mode().Perm(); got != 0o600 {
216			t.Errorf("new secrets file mode = %o, want 600", got)
217		}
218	}
