293	func TestFileStoreRemove(t *testing.T) {
294		t.Run("removes the file and the empty namespace folder", func(t *testing.T) {
295			path := secretsPathIn(t)
296			store := newTestStore(t, path)
297			if err := store.Save(Secrets{AdminPassword: "x"}); err != nil {
298				t.Fatal(err)
299			}
300			if err := store.Remove(); err != nil {
301				t.Fatalf("Remove: %v", err)
302			}
303			if _, err := os.Stat(path); !os.IsNotExist(err) {
304				t.Errorf("the secrets file is still there (stat error = %v)", err)
305			}
306			if _, err := os.Stat(filepath.Dir(path)); !os.IsNotExist(err) {
307				t.Errorf("the empty namespace folder is still there (stat error = %v)", err)
308			}
309			if _, found, err := store.Load(); err != nil || found {
310				t.Errorf("Load after Remove = (found %v, err %v), want (false, nil)", found, err)
311			}
312		})
313	
314		t.Run("is idempotent", func(t *testing.T) {
315			store := newTestStore(t, secretsPathIn(t))
316			for i := 0; i < 3; i++ {
317				if err := store.Remove(); err != nil {
318					t.Fatalf("Remove #%d on an absent file: %v", i+1, err)
319				}
320			}
321			if err := store.Save(Secrets{AdminPassword: "x"}); err != nil {
322				t.Fatal(err)
323			}
324			for i := 0; i < 2; i++ {
325				if err := store.Remove(); err != nil {
326					t.Fatalf("Remove #%d after a Save: %v", i+1, err)
327				}
328			}
329		})
330	
331		t.Run("keeps a namespace folder that holds something else", func(t *testing.T) {
332			path := secretsPathIn(t)
333			store := newTestStore(t, path)
334			if err := store.Save(Secrets{AdminPassword: "x"}); err != nil {
335				t.Fatal(err)
336			}
337			other := filepath.Join(filepath.Dir(path), "notes.txt")
338			if err := os.WriteFile(other, []byte("keep me"), 0o600); err != nil {
339				t.Fatal(err)
340			}
341			if err := store.Remove(); err != nil {
342				t.Fatalf("Remove: %v", err)
343			}
344			if _, err := os.Stat(other); err != nil {
345				t.Errorf("Remove deleted a file it does not own: %v", err)
346			}
347		})
348	}
