356	// gitRepo makes a repository in a temp dir, isolated from the user's git
357	// configuration (a global excludes file could ignore anything).
358	func gitRepo(t *testing.T) string {
359		t.Helper()
360		if _, err := exec.LookPath("git"); err != nil {
361			t.Skip("git is not installed")
362		}
363		home := t.TempDir()
364		t.Setenv("HOME", home)
365		t.Setenv("USERPROFILE", home)
366		t.Setenv("XDG_CONFIG_HOME", filepath.Join(home, ".config"))
367		t.Setenv("GIT_CONFIG_GLOBAL", os.DevNull)
368		t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
369	
370		repo := t.TempDir()
371		cmd := exec.Command("git", "init", "-q")
372		cmd.Dir = repo
373		if out, err := cmd.CombinedOutput(); err != nil {
374			t.Fatalf("git init: %v\n%s", err, out)
375		}
376		return repo
377	}
