431	// assertOnlyEntries fails unless dir holds exactly the named entries: no
432	// temporary file left behind.
433	func assertOnlyEntries(t *testing.T, dir string, want ...string) {
434		t.Helper()
435		entries, err := os.ReadDir(dir)
436		if err != nil {
437			t.Fatal(err)
438		}
439		var got []string
440		for _, e := range entries {
441			got = append(got, e.Name())
442		}
443		if !reflect.DeepEqual(got, want) {
444			t.Errorf("entries of %s = %v, want %v (no temporary file may remain)", dir, got, want)
445		}
446	}
