282	// topLevelKeys returns the keys of the outermost JSON object, in file order.
283	func topLevelKeys(t *testing.T, data []byte) []string {
284		t.Helper()
285		dec := json.NewDecoder(bytes.NewReader(data))
286		if tok, err := dec.Token(); err != nil || tok != json.Delim('{') {
287			t.Fatalf("the descriptor is not a JSON object: %v %v", tok, err)
288		}
289		var keys []string
290		for dec.More() {
291			tok, err := dec.Token()
292			if err != nil {
293				t.Fatal(err)
294			}
295			keys = append(keys, tok.(string))
296			var skipped json.RawMessage
297			if err := dec.Decode(&skipped); err != nil {
298				t.Fatal(err)
299			}
300		}
301		return keys
302	}
