405			want    string // lower-case fragment the error must hold
406		}{
407			{"schemaVersion 2", bytes.Replace(good, []byte(`"schemaVersion": 1`), []byte(`"schemaVersion": 2`), 1), "schema"},
408			{"schemaVersion 0", bytes.Replace(good, []byte(`"schemaVersion": 1`), []byte(`"schemaVersion": 0`), 1), "schema"},
409			{"schemaVersion missing", bytes.Replace(good, []byte("  \"schemaVersion\": 1,\n"), nil, 1), "schema"},
