506	// assertPackageDescriptorPath checks that got is internal/nexusbench/descriptor.json.
507	// It only compares paths: the versioned file itself is never written by a test.
508	func assertPackageDescriptorPath(t *testing.T, got string) {
509		t.Helper()
510		if !filepath.IsAbs(got) {
511			t.Errorf("DescriptorPath() = %q, want an absolute path", got)
512		}
513		if filepath.Base(got) != "descriptor.json" {
514			t.Errorf("DescriptorPath() = %q, want a file named descriptor.json", got)
515		}
516		if dir := filepath.ToSlash(filepath.Dir(got)); !strings.HasSuffix(dir, "/internal/nexusbench") {
517			t.Errorf("DescriptorPath() is in %q, want the internal/nexusbench folder", dir)
518		}
519		if _, err := os.Stat(filepath.Join(filepath.Dir(got), "doc.go")); err != nil {
520			t.Errorf("DescriptorPath() folder does not hold the package sources: %v", err)
521		}
522	}
