234	// itself is left untouched. A value that cannot be parsed is an error that names
235	// its variable. Setting only NEXUS_BENCH_NAMESPACE moves the upstream URL to the
236	// new namespace, unless base already carries a custom one or
237	// NEXUS_BENCH_UPSTREAM_URL is set. FromEnv checks the shape of numbers,
238	// durations and booleans only; Validate checks the values.
239	func FromEnv(base Params, getenv func(string) string) (Params, error) {
240		p := base
241		if base.Hosts != nil {
242			p.Hosts = append([]string(nil), base.Hosts...)
243		}
244	
245		followsNamespace := base.UpstreamURL == upstreamFor(base.Namespace)
246		if v := getenv(envNamespace); v != "" {
247			p.Namespace = v
248		}
249		for _, s := range envSetters {
250			v := getenv(s.name)
251			if v == "" {
252				continue
253			}
254			if err := s.apply(&p, v); err != nil {
255				return base, err
256			}
257		}
258		if followsNamespace && getenv(envUpstreamURL) == "" {
259			p.UpstreamURL = upstreamFor(p.Namespace)
260		}
261		return p, nil
262	}
263	
264	// splitList splits a comma-separated list, trimming blanks and dropping empty items.
265	func splitList(v string) []string {
266		var out []string
267		for _, item := range strings.Split(v, ",") {
268			if item = strings.TrimSpace(item); item != "" {
269				out = append(out, item)
270			}
271		}
272		return out
273	}
274	
275	// Validate refuses any value the bench must not act on or render into a
276	// manifest. It reports every problem at once, each naming its variable, and
277	// never contacts the cluster.
278	func (p Params) Validate() error {
279		var errs []error
280		add := func(err error) {
281			if err != nil {
282				errs = append(errs, err)
283			}
284		}
285	
286		add(validateContext(p.Context))
287		add(validateNamespace(p.Namespace))
288		add(validateNodePort(envHTTPNodePort, p.HTTPNodePort))
289		add(validateNodePort(envDockerNodePort, p.DockerNodePort))
290		if p.HTTPNodePort == p.DockerNodePort {
291			add(fmt.Errorf("%s and %s are both %d: the two NodePorts must differ", envHTTPNodePort, envDockerNodePort, p.HTTPNodePort))
292		}
293		add(validateQuantity(envCPURequest, p.CPURequest, parseCPU, "cores such as 2 or 500m"))
294		add(validateQuantity(envCPULimit, p.CPULimit, parseCPU, "cores such as 2 or 500m"))
295		add(validateQuantity(envMemoryRequest, p.MemoryRequest, parseBytes, "bytes such as 3Gi"))
296		add(validateQuantity(envMemoryLimit, p.MemoryLimit, parseBytes, "bytes such as 4Gi"))
297		add(validateQuantity(envStorageSize, p.StorageSize, parseBytes, "bytes such as 5Gi"))
298		add(validateRequestLimit(envCPURequest, p.CPURequest, envCPULimit, p.CPULimit, parseCPU))
299		add(validateRequestLimit(envMemoryRequest, p.MemoryRequest, envMemoryLimit, p.MemoryLimit, parseBytes))
300		add(validateJVMOpts(p.JVMOpts))
301		add(validateImage(p.Image, p.ImageTag))
302		add(validateUpstreamURL(p.UpstreamURL))
303		add(validateHosts(p.Hosts))
304		add(validateTimeout(envTimeout, p.Timeout))
305		add(validateTimeout(envDeleteTimeout, p.DeleteTimeout))
306		add(validatePath(envSecrets, p.SecretsPath))
307		add(validatePath(envDescriptor, p.DescriptorPath))
308		return errors.Join(errs...)
309	}
