311	func validateContext(v string) error {
312		if len(v) > maxContextLen || !contextName.MatchString(v) {
313			return fmt.Errorf("%s: %q is not a usable context name (letters, digits, '.', '_', '@' and '-', starting with a letter or digit)", envContext, v)
314		}
315		return nil
316	}
317	
318	func validateNamespace(v string) error {
319		lower := strings.ToLower(v)
320		reserved := reservedNamespaces[lower]
321		for _, prefix := range reservedNamespacePrefixes {
322			reserved = reserved || strings.HasPrefix(lower, prefix)
323		}
324		if reserved {
325			return fmt.Errorf("%s: namespace %q belongs to the cluster or to another project and is never used by the bench (refused: default, kube-*, app-*, flux-system, local-path-storage, traefik, kyverno, observability, plane)", envNamespace, v)
326		}
327		if len(v) > maxNamespaceLen || !dns1123Label.MatchString(v) {
328			return fmt.Errorf("%s: %q is not a Kubernetes namespace name (lower-case letters, digits and '-', %d characters at most, starting and ending with a letter or digit)", envNamespace, v, maxNamespaceLen)
329		}
330		return nil
331	}
332	
333	func validateNodePort(name string, port int) error {
334		if port < nodePortMin || port > nodePortMax {
335			return fmt.Errorf("%s: %d is outside the NodePort range %d-%d", name, port, nodePortMin, nodePortMax)
336		}
337		return nil
338	}
339	
340	// quantityParser turns a Kubernetes quantity into a comparable amount (milli-cores
341	// or bytes); ok is false when the text is not a quantity of that kind.
342	type quantityParser func(v string) (amount *big.Rat, ok bool)
343	
344	// parseCPU returns a CPU quantity in milli-cores. big.Rat keeps "0.0005" and
345	// huge values exact, which an int64 would not.
346	func parseCPU(v string) (*big.Rat, bool) {
347		if !cpuQuantity.MatchString(v) {
348			return nil, false
349		}
350		number, milli := strings.CutSuffix(v, "m")
351		r, ok := new(big.Rat).SetString(number)
352		if !ok {
353			return nil, false
354		}
355		if !milli {
356			r.Mul(r, big.NewRat(1000, 1))
357		}
358		return r, true
359	}
360	
361	// byteMultipliers maps the suffixes byteQuantity accepts to their value in bytes.
362	var byteMultipliers = map[string]*big.Int{
363		"":   big.NewInt(1),
364		"Ki": new(big.Int).Lsh(big.NewInt(1), 10),
365		"Mi": new(big.Int).Lsh(big.NewInt(1), 20),
366		"Gi": new(big.Int).Lsh(big.NewInt(1), 30),
367		"Ti": new(big.Int).Lsh(big.NewInt(1), 40),
368		"Pi": new(big.Int).Lsh(big.NewInt(1), 50),
369		"Ei": new(big.Int).Lsh(big.NewInt(1), 60),
370		"k":  big.NewInt(1e3),
371		"M":  big.NewInt(1e6),
372		"G":  big.NewInt(1e9),
373		"T":  big.NewInt(1e12),
374		"P":  big.NewInt(1e15),
375		"E":  big.NewInt(1e18),
376	}
377	
378	// parseBytes returns a quantity of bytes.
379	func parseBytes(v string) (*big.Rat, bool) {
380		m := byteQuantity.FindStringSubmatch(v)
381		if m == nil {
382			return nil, false
383		}
384		r, ok := new(big.Rat).SetString(m[1])
385		if !ok {
386			return nil, false
387		}
388		return r.Mul(r, new(big.Rat).SetInt(byteMultipliers[m[2]])), true
389	}
390	
391	func validateQuantity(name, v string, parse quantityParser, hint string) error {
392		amount, ok := parse(v)
393		if !ok {
394			return fmt.Errorf("%s: %q is not a Kubernetes quantity of %s", name, v, hint)
395		}
396		if amount.Sign() == 0 {
397			return fmt.Errorf("%s: %q is zero; the quantity must be greater than zero", name, v)
398		}
399		return nil
400	}
401	
402	// validateRequestLimit refuses a request above its limit, which Kubernetes
403	// rejects at admission. A value that is not a quantity is reported by
404	// validateQuantity, not here.
405	func validateRequestLimit(requestName, request, limitName, limit string, parse quantityParser) error {
406		req, okReq := parse(request)
407		lim, okLim := parse(limit)
408		if okReq && okLim && req.Cmp(lim) > 0 {
409			return fmt.Errorf("%s and %s: the request %q is above the limit %q; the request must not exceed the limit", requestName, limitName, request, limit)
410		}
411		return nil
412	}
413	
414	func validateJVMOpts(v string) error {
415		if v == "" || len(v) > maxJVMOptsLen || !jvmOptsChars.MatchString(v) {
416			return fmt.Errorf("%s: %q must be 1-%d characters among letters, digits, space and _ . , : = / + @ %% -", envJVMOpts, v, maxJVMOptsLen)
417		}
418		// A leading indicator ("- ", "@", "%", ",", ":", a space) would stop the value
419		// from being a plain YAML scalar when it is written unquoted.
420		if !jvmOptsStart.MatchString(v) {
421			return fmt.Errorf("%s: %q must start with a letter, a digit, or '-' followed by a non-space character", envJVMOpts, v)
422		}
423		// ": " and a trailing ":" would turn a plain YAML scalar into a mapping key.
424		if strings.Contains(v, ": ") || strings.HasSuffix(v, ":") {
425			return fmt.Errorf("%s: %q must not hold \": \" or end with a colon", envJVMOpts, v)
426		}
427		return nil
428	}
429	
430	func validateImage(image, tag string) error {
431		if strings.HasPrefix(strings.ToLower(image), zotRegistry) {
432			return fmt.Errorf("%s: %q is in %s, where the Kyverno policy verify-tvp-images only admits signed images and the bench image is not signed; use an image from another registry", envImage, image, zotRegistry)
433		}
434		if len(image) > maxImageLen || !imageChars.MatchString(image) {
435			return fmt.Errorf("%s: %q is not an image name without tag or digest", envImage, image)
436		}
437		if !imageTag.MatchString(tag) {
438			return fmt.Errorf("%s: %q is not an image tag", envImageTag, tag)
439		}
440		return nil
441	}
442	
443	func validateUpstreamURL(v string) error {
444		u, err := url.Parse(v)
445		if err != nil || !urlChars.MatchString(v) {
446			return fmt.Errorf("%s: %q is not a plain http or https URL", envUpstreamURL, v)
447		}
448		if (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" || u.User != nil {
449			return fmt.Errorf("%s: %q must be http:// or https:// followed by a host, without credentials", envUpstreamURL, v)
450		}
451		// url.Parse accepts an empty port ("http://a:") and any digits ("a:99999").
452		if port := u.Port(); port != "" || strings.HasSuffix(u.Host, ":") {
453			if n, err := strconv.Atoi(port); err != nil || n < 1 || n > maxTCPPort {
454				return fmt.Errorf("%s: %q has a port outside 1-%d", envUpstreamURL, v, maxTCPPort)
455			}
456		}
457		return nil
458	}
459	
460	func validateHosts(hosts []string) error {
461		for _, h := range hosts {
462			if net.ParseIP(h) == nil && (len(h) > maxHostLen || !hostName.MatchString(h)) {
463				return fmt.Errorf("%s: %q is not an IP address or a host name", envHosts, h)
464			}
465		}
466		return nil
467	}
468	
469	func validateTimeout(name string, d time.Duration) error {
470		if d <= 0 {
471			return fmt.Errorf("%s: %s must be a positive duration", name, d)
472		}
473		return nil
474	}
475	
476	// validatePath refuses control characters; an empty path means "derived".
477	func validatePath(name, v string) error {
478		if len(v) > maxPathLen || strings.ContainsFunc(v, func(r rune) bool { return r < 0x20 || r == 0x7f }) {
479			return fmt.Errorf("%s: the path is too long or holds a control character", name)
480		}
481		return nil
482	}
