105	// Params is everything that varies between two runs of the bench. Resolve it
106	// with Defaults, then FromEnv, then the command flags, then Validate before any
107	// call to the cluster: the manifests are rendered from validated values only.
108	type Params struct {
109		Context, Namespace, Image, ImageTag string
